import { tetrisReducer, createInitialState } from './src/game/tetrisReducer.js';
import { createBoard, clearLines, collides, createPiece, dropDistance } from './src/game/tetrominoes.js';
import assert from 'node:assert';

// 1) 初始状态
let s = createInitialState();
assert.strictEqual(s.status, 'idle');
assert.strictEqual(s.board.length, 20);
assert.strictEqual(s.board[0].length, 10);

// 2) START -> playing
s = tetrisReducer(s, { type: 'START' });
assert.strictEqual(s.status, 'playing');
const t0 = s.current.type;

// 3) 左右移动 & 边界不越界
let left = s;
for (let i = 0; i < 30; i++) left = tetrisReducer(left, { type: 'MOVE', dir: 'left' });
assert.ok(!collides(left.board, left.current.shape, left.current.x, left.current.y), 'left within bounds');
let right = left;
for (let i = 0; i < 30; i++) right = tetrisReducer(right, { type: 'MOVE', dir: 'right' });
assert.ok(!collides(right.board, right.current.shape, right.current.x, right.current.y), 'right within bounds');

// 4) 旋转不抛错
const rot = tetrisReducer(s, { type: 'ROTATE', dir: 'cw' });
assert.ok(rot.current.shape.length >= 2, 'rotate works');

// 5) 暂停 / 继续
let p = tetrisReducer(s, { type: 'TOGGLE_PAUSE' });
assert.strictEqual(p.status, 'paused');
p = tetrisReducer(p, { type: 'TOGGLE_PAUSE' });
assert.strictEqual(p.status, 'playing');

// 6) 硬降：应固定一格 -> 棋盘出现非空格子
const hd = tetrisReducer(s, { type: 'HARD_DROP' });
const filled = hd.board.flat().filter(Boolean).length;
assert.ok(filled >= 4, `hard drop leaves blocks, got ${filled}`);

// 7) 消行：构造满行
let b = createBoard();
b[19] = Array.from({ length: 10 }, () => '#fff');
b[18] = Array.from({ length: 10 }, () => '#fff');
b[17][0] = '#fff';
const { board: clearedBoard, cleared } = clearLines(b);
assert.strictEqual(cleared, 2, 'clears two full lines');
assert.strictEqual(clearedBoard.flat().filter(Boolean).length, 1, 'one block remains');

// 8) dropDistance 合法
const d = dropDistance(createBoard(), createPiece('I'));
assert.ok(d >= 0 && d <= 20, `drop distance sane: ${d}`);

// 9) 连续硬降直到游戏结束
let g = tetrisReducer(createInitialState(), { type: 'START' });
let guard = 0;
while (g.status === 'playing' && guard++ < 500) {
  g = tetrisReducer(g, { type: 'HARD_DROP' });
}
assert.strictEqual(g.status, 'gameover', 'eventually game over');
assert.ok(g.score > 0, `score accumulated: ${g.score}`);

console.log('ALL LOGIC TESTS PASSED');
console.log('spawned first piece:', t0, '| final score:', g.score, '| lines:', g.lines, '| level:', g.level);
